/*
 * Bakes the pixel-art PNG sheets and atlas JSON for direction C from the code in
 * src/fx/pixel, and writes upscaled previews to docs/art/pixel/. Run from the repo root:
 *   node assets/art/pixel/build.mjs
 * Outputs (assets/art/pixel/): pixel-player, pixel-tiles, pixel-scenery, pixel-hud (PNG + Phaser atlas JSON),
 * pixel-tileset (PNG + index JSON, a uniform 16 x 16 grid for Tilemap layers) and pixel-font (PNG + BMFont XML).
 * All art is generated by this repo's own code (CC0 / MIT, nothing third-party).
 */
import { createServer } from 'vite';
import { deflateSync } from 'node:zlib';
import { mkdirSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..', '..', '..');
const previewDir = path.join(root, 'docs', 'art', 'pixel');
mkdirSync(previewDir, { recursive: true });

// ---- PNG encoder (RGBA8, no interlace, filter 0) ---------------------------
const crcTable = Array.from({ length: 256 }, (_, n) => {
  let c = n;
  for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  return c >>> 0;
});
const crc32 = (buf) => {
  let c = 0xffffffff;
  for (const b of buf) c = crcTable[(c ^ b) & 255] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
};
const chunk = (type, data) => {
  const out = Buffer.alloc(12 + data.length);
  out.writeUInt32BE(data.length, 0);
  out.write(type, 4, 'ascii');
  data.copy(out, 8);
  out.writeUInt32BE(crc32(out.subarray(4, 8 + data.length)), 8 + data.length);
  return out;
};
function encodePng(r) {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(r.width, 0);
  ihdr.writeUInt32BE(r.height, 4);
  ihdr[8] = 8;
  ihdr[9] = 6;
  const raw = Buffer.alloc((r.width * 4 + 1) * r.height);
  for (let y = 0; y < r.height; y++) {
    raw[y * (r.width * 4 + 1)] = 0;
    Buffer.from(r.data.buffer, r.data.byteOffset + y * r.width * 4, r.width * 4).copy(raw, y * (r.width * 4 + 1) + 1);
  }
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', ihdr),
    chunk('IDAT', deflateSync(raw, { level: 9 })),
    chunk('IEND', Buffer.alloc(0)),
  ]);
}

const server = await createServer({
  root,
  configFile: false,
  logLevel: 'silent',
  appType: 'custom',
  server: { middlewareMode: true },
});
try {
  const px = await server.ssrLoadModule('/src/fx/pixel/index.ts');
  const fx = await server.ssrLoadModule('/src/fx/palette.ts');
  const assets = px.buildPixelAssets();
  for (const [name, atlas] of Object.entries(assets)) {
    writeFileSync(path.join(here, `pixel-${name}.png`), encodePng(atlas.sheet));
    writeFileSync(path.join(here, `pixel-${name}.json`), JSON.stringify(atlas.json, null, 1) + '\n');
  }
  const font = px.bakeFontSheet();
  writeFileSync(path.join(here, 'pixel-font.png'), encodePng(font));
  writeFileSync(path.join(here, 'pixel-font.xml'), px.fontXml());
  const bg = (speed) => fx.backgroundForSpeed(speed, 12);

  // ---- preview 1: every player frame, both runners, yellow, plus all bands idle ----
  const K = 3;
  const sheet = px.createRaster(14 * 20 + 10, 6 * 28 + 10);
  const field = px.rgba(bg(0));
  px.fillRect(sheet, 0, 0, sheet.width, sheet.height, field);
  const place = (frame, x, y) => px.blit(sheet, frame, x, y);
  let row = 0;
  for (const variant of ['runner', 'twin']) {
    px.PLAYER_FRAMES.forEach((def, i) => place(px.bakePlayerFrame(variant, 'yellow', def), 5 + (i % 14) * 20, 5 + (row + Math.floor(i / 14)) * 28));
    row += 2;
  }
  ['white', 'blue', 'green', 'yellow', 'red'].forEach((band, i) => {
    place(px.bakePlayerFrame('runner', band, px.PLAYER_FRAMES[0]), 5 + i * 20, 5 + 4 * 28);
    place(px.bakePlayerFrame('twin', band, px.PLAYER_FRAMES[0]), 5 + (i + 6) * 20, 5 + 4 * 28);
    place(px.bakePlayerFrame('runner', band, px.PLAYER_FRAMES.find((f) => f.name === 'run_1')), 5 + i * 20, 5 + 5 * 28);
    place(px.bakePlayerFrame('twin', band, px.PLAYER_FRAMES.find((f) => f.name === 'sprint_2')), 5 + (i + 6) * 20, 5 + 5 * 28);
  });
  writeFileSync(path.join(previewDir, 'player-frames.png'), encodePng(px.upscale(sheet, K)));

  // ---- preview 2: the w0-02 slice assembled only from baked assets (480x270 -> 960x540) ----
  const GRID = [
    '..............................', '..............................', '..............................',
    '..............................', '..............................', '..............................',
    '.....................#########', '.....................#########', '..............................',
    '..............................', '..............................', '..............................',
    '##########RRRRR######.YYY#BBB#', '##########.....######....#...#', '##########.....######....#...#',
    '##########.....######....#.E.#', '##########.....######....#####',
  ];
  const BAND_OF = { B: 'blue', G: 'green', Y: 'yellow', R: 'red' };
  const at = (c, r) => (r < 0 || r >= GRID.length || c < 0 || c >= GRID[0].length ? '.' : GRID[r][c]);
  const compose = (band, speed, runner, frameName) => {
    const out = px.createRaster(480, 270);
    const colors = px.sceneryColors(speed, 12);
    px.fillRect(out, 0, 0, 480, 270, px.rgba(colors.base));
    const tintMask = (mask, color, x, y, alpha = 255) => {
      for (let j = 0; j < mask.height; j++) for (let i = 0; i < mask.width; i++) if (px.getPixel(mask, i, j)[3] > 0) px.setPixel(out, x + i, y + j, px.rgba(color, alpha));
    };
    const horizon = px.bakeHorizon();
    const hz = px.createRaster(480, 270);
    for (let j = 0; j < 270; j++) for (let i = 0; i < 480; i++) if (px.getPixel(horizon, i, j)[3] > 0 && px.bayer(i, j) < colors.horizonAlpha) px.setPixel(hz, i, j, [255, 255, 255, 255]);
    tintMask(hz, colors.hue, 0, 0);
    tintMask(px.bakeStars(), colors.star, 0, 0);
    tintMask(px.bakeRidge('far'), colors.ridgeFar, 0, px.RIDGES.far.top);
    tintMask(px.bakeRidge('near'), colors.ridgeNear, 0, px.RIDGES.near.top);
    for (let r = 0; r < GRID.length; r++) {
      for (let c = 0; c < 30; c++) {
        const ch = at(c, r);
        if (ch === '.') continue;
        const x = c * 16;
        const y = r * 16 - 2;
        const same = (dc, dr) => at(c + dc, r + dr) === ch;
        const n = { up: same(0, -1), right: same(1, 0), down: same(0, 1), left: same(-1, 0) };
        if (ch === '#') {
          let depth = 0;
          for (let k = 1; k <= 4 && at(c, r - k) === '#'; k++) depth = k;
          px.blit(out, px.bakeSafeTile(n, depth), x, y);
        } else if (ch === 'E') {
          px.blit(out, px.bakeExitGlow(1), x - 8, y - 8);
          px.blit(out, px.bakeExitDoor(1), x, y);
        } else {
          const b = BAND_OF[ch];
          px.blit(out, b === band ? px.bakeSolidTile(b, n) : px.bakeGhostTile(b), x, y);
        }
      }
    }
    const def = px.PLAYER_FRAMES.find((f) => f.name === frameName);
    px.blit(out, px.bakePlayerFrame(runner, band, def), 100 - 10, 190 - 26);
    return out;
  };
  writeFileSync(path.join(previewDir, 'scene-yellow.png'), encodePng(px.upscale(compose('yellow', 9, 'runner', 'run_2'), 2)));
  writeFileSync(path.join(previewDir, 'scene-red.png'), encodePng(px.upscale(compose('red', 12, 'runner', 'sprint_2'), 2)));
  writeFileSync(path.join(previewDir, 'scene-white-b.png'), encodePng(px.upscale(compose('white', 0, 'twin', 'idle_0'), 2)));

  // ---- Tandem previews: the two-lane scene (HUD strips, parked twin, edge arrow) and the vision simulations ----
  const col = await server.ssrLoadModule('/src/fx/color.ts');
  const ui = fx.palette.ui;
  const drawText = (out, text, x, y, hex, scale = 1) => {
    const c = px.rgba(col.hexToRgb(hex));
    [...text].forEach((ch, n) => {
      const r = px.glyphRect(ch);
      for (let j = 0; j < r.h; j++) for (let i = 0; i < r.w; i++) if (px.getPixel(font, r.x + i, r.y + j)[3] > 0) px.fillRect(out, x + n * 6 * scale + i * scale, y + j * scale, scale, scale, c);
    });
  };
  const sampleLines = [
    'REDSHIFT  0123456789  M:SS.ss  GEAR 3 > 4',
    'ABCDEFGHIJKLMNOPQRSTUVWXYZ',
    'abcdefghijklmnopqrstuvwxyz',
    String.raw`!"#$%&'()*+,-./:;<=>?@[\]^_{|}~` + '`',
    'Press Shift to shift gears — Q E Z X also work',
    '← ↑ → ↓ ⇧ ▲ ▼ ▶ ◀ ✓ ○ ● ★ ' + String.fromCharCode(0xe000) + ' · × …',
  ];
  const sampleSheet = px.createRaster(270, 8 * sampleLines.length + 12);
  px.fillRect(sampleSheet, 0, 0, sampleSheet.width, sampleSheet.height, px.rgba(col.hexToRgb(ui.panel)));
  sampleLines.forEach((line, i) => drawText(sampleSheet, line, 5, 6 + i * 9, ui.text));
  writeFileSync(path.join(previewDir, 'font-sample.png'), encodePng(px.upscale(sampleSheet, 3)));
  const tintBlit = (out, mask, x, y, hex) => {
    const c = px.rgba(col.hexToRgb(hex));
    for (let j = 0; j < mask.height; j++) for (let i = 0; i < mask.width; i++) if (px.getPixel(mask, i, j)[3] > 0) px.setPixel(out, x + i, y + j, c);
  };
  const strip = (out, y, body, band, label, parked) => {
    px.fillRect(out, 5, y, 110, 14, px.rgba(col.hexToRgb(fx.palette.ui.panelBorder)));
    px.fillRect(out, 6, y + 1, 108, 12, px.rgba(col.hexToRgb(ui.panel)));
    tintBlit(out, px.bakeBodyGlyph(body), 9, y + 1, parked ? ui.textMuted : fx.palette.gears[band].solid.fill);
    drawText(out, label, 20, y + 3, parked ? ui.textMuted : ui.text);
    if (parked) tintBlit(out, px.bakeHomeGlyph(), 103, y + 3, ui.textMuted);
    else for (let g = 0; g < 4; g++) px.fillRect(out, 60 + g * 13, y + 3, 11, 8, px.rgba(col.hexToRgb(fx.palette.gears[['blue', 'green', 'yellow', 'red'][g]].solid.fill)));
  };
  const LANES = [
    '..............................',
    '..............................',
    '..............................',
    '..............................',
    '..............................',
    '.................YYYYY........',
    '..............................',
    '##############################',
    '..............................',
    '..............................',
    '...........BBBB...............',
    '..............................',
    '..............................',
    '.......................E......',
    '##########..########GGGG######',
  ];
  const lane = (band, parked) => {
    const out = px.createRaster(480, 270);
    px.fillRect(out, 0, 0, 480, 270, px.rgba(fx.backgroundForSpeed(9, 12)));
    const at = (c, r) => (r < 0 || r >= LANES.length || c < 0 || c >= 30 ? '.' : LANES[r][c]);
    const BAND_OF = { B: 'blue', G: 'green', Y: 'yellow', R: 'red' };
    for (let r = 0; r < LANES.length; r++) {
      for (let c = 0; c < 30; c++) {
        const ch = at(c, r);
        if (ch === '.') continue;
        const x = c * 16;
        const y = 30 + r * 16;
        const same = (dc, dr) => at(c + dc, r + dr) === ch;
        const n = { up: same(0, -1), right: same(1, 0), down: same(0, 1), left: same(-1, 0) };
        if (ch === '#') {
          let depth = 0;
          for (let k = 1; k <= 4 && at(c, r - k) === '#'; k++) depth = k;
          px.blit(out, px.bakeSafeTile(n, depth), x, y);
        } else if (ch === 'E') {
          px.blit(out, px.bakeExitGlow(1), x - 8, y - 8);
          px.blit(out, px.bakeExitDoor(1), x, y);
        } else {
          const b = BAND_OF[ch];
          px.blit(out, b === (r < 7 ? band[0] : band[1]) ? px.bakeSolidTile(b, n) : px.bakeGhostTile(b), x, y);
        }
      }
    }
    const frame = (v, b, name) => px.bakePlayerFrame(v, b, px.PLAYER_FRAMES.find((f) => f.name === name));
    // runner (upper lane) stands on the divider top; twin (lower lane) on its floor, or parked at the exit
    px.blit(out, frame('runner', band[0], 'sprint_2'), 120 - 10, 30 + 7 * 16 - 26);
    px.blit(out, parked ? frame('twin', band[1], 'park_0') : frame('twin', band[1], 'run_1'), (parked ? 23 * 16 + 8 : 120) - 10, 30 + 14 * 16 - 26);
    px.blit(out, px.bakeEdgeArrow('twin', band[1]), 480 - 22, 30 + 3 * 16);
    px.blit(out, px.bakeExitArrow(), 480 - 22, 30 + 5 * 16);
    strip(out, 5, 'runner', band[0], 'RUN 4', false);
    strip(out, 21, 'twin', band[1], parked ? 'HOME' : 'RUN 2', parked);
    return out;
  };
  writeFileSync(path.join(previewDir, 'tandem-scene.png'), encodePng(px.upscale(lane(['yellow', 'blue'], false), 2)));
  writeFileSync(path.join(previewDir, 'tandem-parked.png'), encodePng(px.upscale(lane(['red', 'green'], true), 2)));

  // vision simulations: runner and twin side by side, every band, idle, parked and sprint, plus the glyphs and the arrow
  const sim = (raster, vision) => {
    const out = px.createRaster(raster.width, raster.height);
    for (let y = 0; y < raster.height; y++) {
      for (let x = 0; x < raster.width; x++) {
        const p = px.getPixel(raster, x, y);
        if (p[3] === 0) continue;
        const c = col.simulateVision({ r: p[0], g: p[1], b: p[2] }, vision);
        px.setPixel(out, x, y, px.rgba(c, p[3]));
      }
    }
    return out;
  };
  const cell = [['runner', 'idle_0'], ['twin', 'idle_0'], ['runner', 'park_0'], ['twin', 'park_0'], ['runner', 'sprint_2'], ['twin', 'sprint_2']];
  const bandsAll = ['white', 'blue', 'green', 'yellow', 'red'];
  const blockW = cell.length * 20 + 2 * 24 + 6;
  const blockH = 5 * 28 + 12;
  const sheetAll = px.createRaster(col.VISIONS.length * blockW + 6, blockH + 6 + 12);
  px.fillRect(sheetAll, 0, 0, sheetAll.width, sheetAll.height, px.rgba(col.hexToRgb(fx.palette.background)));
  col.VISIONS.forEach((vision, vi) => {
    const ox = 6 + vi * blockW;
    drawText(sheetAll, vision === 'protanopia' ? 'PROTAN' : vision === 'deuteranopia' ? 'DEUTAN' : vision === 'tritanopia' ? 'TRITAN' : vision.toUpperCase(), ox, 3, ui.text);
    bandsAll.forEach((band, bi) => {
      const oy = 12 + bi * 28;
      cell.forEach(([v, name], ci) => {
        const f = px.bakePlayerFrame(v, band, px.PLAYER_FRAMES.find((d) => d.name === name));
        px.blit(sheetAll, sim(f, vision), ox + ci * 20, oy);
      });
      px.blit(sheetAll, sim(px.bakeEdgeArrow('runner', band), vision), ox + cell.length * 20 + 1, oy + 6);
      px.blit(sheetAll, sim(px.bakeEdgeArrow('twin', band), vision), ox + cell.length * 20 + 25, oy + 6);
    });
  });
  writeFileSync(path.join(previewDir, 'tandem-vision.png'), encodePng(px.upscale(sheetAll, 2)));

  // ---- tiles under the vision simulations (M2-14b): solid and ghost of every band plus the safe tile, on the standing field ----
  {
    const none = { up: false, right: false, down: false, left: false };
    const kinds = [...bandsAll.map((b) => ['solid', b]), ...bandsAll.slice(1).map((b) => ['ghost', b]), ['safe', 'safe']];
    const gap = 20;
    const rowH = 22;
    const labelW = 44;
    const out = px.createRaster(labelW + kinds.length * gap + 6, col.VISIONS.length * rowH + 6);
    px.fillRect(out, 0, 0, out.width, out.height, px.rgba(col.hexToRgb(fx.palette.background)));
    col.VISIONS.forEach((vision, vi) => {
      const oy = 4 + vi * rowH;
      drawText(out, vision === 'protanopia' ? 'PROTAN' : vision === 'deuteranopia' ? 'DEUTAN' : vision === 'tritanopia' ? 'TRITAN' : vision.toUpperCase(), 3, oy + 5, ui.text);
      kinds.forEach(([kind, band], ki) => {
        const t = kind === 'solid' ? px.bakeSolidTile(band, none) : kind === 'ghost' ? px.bakeGhostTile(band) : px.bakeSafeTile(none, 0);
        px.blit(out, sim(t, vision), labelW + ki * gap, oy);
      });
    });
    writeFileSync(path.join(previewDir, 'tiles-vision.png'), encodePng(px.upscale(out, 3)));
  }

  // ---- effects preview: dust on land, ring burst, speed lines (tinted as the scene would), on the red and yellow fields ----
  const fxPreview = (speed, band) => {
    const out = px.createRaster(330, 70);
    px.fillRect(out, 0, 0, out.width, out.height, px.rgba(fx.backgroundForSpeed(speed, 12)));
    const outline = fx.palette.gears[band].solid.outline;
    for (let n = 0; n < px.DUST_FRAMES; n++) {
      px.blit(out, px.bakePlayerFrame('runner', band, px.PLAYER_FRAMES.find((f) => f.name === 'land_0')), 6 + n * 30 + 2, 6);
      tintBlit(out, px.bakeDustFrame(n), 6 + n * 30, 6 + 26, ui.textMuted);
    }
    for (let n = 0; n < px.RING_FRAMES; n++) tintBlit(out, px.bakeRingFrame(n), 130 + n * 50, 0, outline);
    let y = 44;
    for (const len of px.SPEED_LENGTHS) {
      px.SPEED_PHASES.forEach((_, ph) => {
        tintBlit(out, px.bakeSpeedLine(len, ph), 8 + ph * 40 + (len === 32 ? 70 : len === 20 ? 35 : 0), y + (ph * 6), outline);
      });
      y += 2;
    }
    return out;
  };
  writeFileSync(path.join(previewDir, 'effects-yellow.png'), encodePng(px.upscale(fxPreview(9, 'yellow'), 4)));
  writeFileSync(path.join(previewDir, 'effects-red.png'), encodePng(px.upscale(fxPreview(12, 'red'), 4)));

  // ---- wipe preview: standing field | yellow field | wipe frame 0 | wipe frame 1 (white at flash.alpha), 120 x 68 crops ----
  {
    const W = 120, H = 68;
    const out = px.createRaster(W * 4 + 3 * 2, H);
    px.fillRect(out, 0, 0, out.width, out.height, px.rgba(col.hexToRgb('#FFFFFF')));
    const a = fx.palette.flash.alpha;
    const panel = (i, color, wipe) => {
      px.fillRect(out, i * (W + 2), 0, W, H, px.rgba(color));
      if (wipe === undefined) return;
      const mask = px.bakeWipeFrame(wipe);
      const lit = col.composite(col.hexToRgb(fx.palette.flash.color), color, a);
      for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) if (px.getPixel(mask, x + 200, y + 100)[3] > 0) px.setPixel(out, i * (W + 2) + x, y, px.rgba(lit));
    };
    panel(0, bg(0));
    panel(1, bg(9));
    panel(2, bg(9), 0);
    panel(3, bg(9), 1);
    writeFileSync(path.join(previewDir, 'wipe-and-yellow.png'), encodePng(px.upscale(out, 3)));
  }
} finally {
  await server.close();
}
